// 原resolve纯组件验证真实移动/自动命令/兵员分类；不替代Common结算或Military10冷银行。
#include "resident/domains/military/military_rout_orders.hpp"
#include "resident/domains/military/military_rout_disposition.hpp"
#include "resident/domains/military/military_round_rng.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;
void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
template<class T>T take(Outcome<T> value){if(!value.ok)throw std::runtime_error(value.error.original.code+":"+value.error.original.path);return std::move(value.value);}
void good(Status value){if(!value.ok)throw std::runtime_error(value.error.original.code+":"+value.error.original.path);}
MilitaryBattleCatalog catalog(){MilitaryBattleCatalog c;c.rout_retreat_enabled=true;BattlefieldDefinition b;b.id="field";b.objective_id="goal";b.rout_retreat=MilitaryRoutRetreatRule{};for(Integer q=0;q<7;++q){HexCell x;x.q=q;x.terrain="plain";b.cells.push_back(x);}b.spawns={{0,{0,0},{}},{1,{6,0},{}}};b.exits=b.spawns;c.battlefields={b};BattleObjectiveDefinition goal;goal.id="goal";goal.kind="repel";goal.side=0;goal.max_rounds=20;c.objectives={goal};TroopDefinition t;t.id="foot";t.category="infantry";t.movement=2;t.minimum_range=t.maximum_range=1;t.attack=1;t.accuracy=100;t.movement_costs={{"plain",1},{"forest",1},{"hill",1},{"water",0},{"wall",0}};c.troop_types={t};return c;}
MilitaryBattleRecord frame(){MilitaryBattleRecord b;b.id="battle:1";b.battlefield_id="field";b.objective_id="goal";b.round=2;b.rout_retreat_enabled=true;b.controller_actor_id="enemy-officer";b.controller_side=1;b.command_scope="unit";b.command_unit_ids={"enemy"};BattleUnit a;a.unit_id="unit";a.army_id="army:1";a.commander_actor_id="officer";a.troop_type_id="foot";a.position={4,0};a.morale=0;a.fit=a.member_ids={"a","b","c"};BattleUnit e=a;e.unit_id="enemy";e.army_id="army:2";e.commander_actor_id=b.controller_actor_id;e.side=1;e.position={6,0};e.heading=3;e.morale=50;e.fit=e.member_ids={"d","e","f"};b.units={a,e};good(write_military_rout_progress(b,{{"unit",1,0}}));return b;}
MilitaryOrders hold(const MilitaryBattleRecord& b){return {{"enemy",{"wait",b.units[1].position,b.units[1].heading,{},{},{}}}};}
MilitaryBattleRecord resolve(MilitaryBattleRecord b,const MilitaryBattleCatalog& c){b.ai_plans=take(make_military_ai(b,c));return take(resolve_military_round(b,c,b.controller_actor_id,hold(b),military_round_random_draw));}
}
int main(){try{auto c=catalog();auto b=frame();auto first=resolve(b,c);check(first.units[0].position==HexPoint{2,0}&&first.units[0].morale==0&&first.phase=="planning","real round moves automatic retreat and cannot revive morale");check(first.units[0].fit==b.units[0].fit&&first.units[0].captured.empty()&&first.units[0].deserted.empty(),"first round preserves real roster");check(first.rng_seed==b.rng_seed&&first.rng_state==b.rng_state,"retreat alone draws no random number");auto second=resolve(first,c);check(second.units[0].position==HexPoint{0,0}&&second.units[0].withdrawn&&second.units[0].fit==b.units[0].fit,"second actual round reaches exit with surviving soldiers");check(second.phase=="result"&&take(read_military_rout_progress(second,c)).empty(),"exit ends rout progress and original objective resolves");
 auto blocked=b;blocked.units[1].position={3,0};auto once=resolve(blocked,c);check(take(read_military_rout_progress(once,c))[0].blocked_rounds==1&&!once.units[0].fit.empty(),"first blocked original round cannot capture");auto twice=resolve(once,c);check(twice.units[0].fit.empty()&&twice.units[0].captured==blocked.units[0].fit&&twice.units[0].dead.empty()&&twice.units[0].deserted.empty(),"second blocked original round captures exact original pool");bool keeper=false;for(const auto& e:twice.last_events)if(e.kind=="rout"&&e.captor_unit_id=="enemy"&&e.captor_army_id=="army:2")keeper=true;check(keeper,"actual adjacent enemy is original settlement custodian");
 auto manual=b;manual.controller_actor_id="officer";manual.controller_side=0;manual.command_unit_ids={"unit"};check(!validate_military_orders(manual,c,"officer",{{"unit",{"wait",manual.units[0].position,0,{},{},{}}}}).ok,"player cannot replace automatic retreat with wait");auto tampered=b;tampered.ai_plans={{"unit",{"rout_move",{0,0},0,{},{},{}}}};check(!resolve_military_round(tampered,c,tampered.controller_actor_id,hold(tampered),{}).ok,"stored automatic plan cannot teleport");auto legacy=c;legacy.rout_retreat_enabled=false;check(!validate_military_battle(b,legacy).ok,"old profile rejects new routed state");auto ordinary=b;ordinary.rout_retreat_enabled=false;ordinary.units[0].morale=50;ordinary.units[0].statuses.clear();auto old=resolve(ordinary,legacy),same=resolve(ordinary,c);check(old.units[0].position==same.units[0].position&&old.units[0].morale==same.units[0].morale&&old.rng_state==same.rng_state,"unselected original session unaffected by loaded new board");
 std::cout<<"MILITARY_ROUT_ROUND="<<checks<<" FAILURES=0 SCOPE=ORIGINAL_ROUND_DOMAIN\n";return 0;}catch(const std::exception& e){std::cerr<<"MILITARY_ROUT_ROUND_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
